package main
import("strings";"testing")
func fixture(source string)Input{a:=strings.Index(source,"func reorder");b:=strings.LastIndex(source,"reorder(");return Input{Mode:"plan",Sources:[]Source{{"file:///fixture/main.go",source}},Target:Location{"file:///fixture/main.go",Range{position(source,a),position(source,a)}},References:[]Location{{"file:///fixture/main.go",Range{position(source,b),position(source,b+7)}}},Signature:"func(b int, a int)"}}
func TestCapturesOriginalArgumentOrder(t *testing.T){s:="package p\nfunc reorder(a int,b int){}\nfunc call(){reorder(first(),second())}\n";out:=run(fixture(s));if !out.Passed||out.Checked!=1{t.Fatal(out)};edit:=out.Changes["file:///fixture/main.go"][1].NewText;if !strings.Contains(edit,"var _goforgeArg0 int = first()\n\tvar _goforgeArg1 int = second()\n\treorder(_goforgeArg1, _goforgeArg0)"){t.Fatal(edit)}}
func TestFreshNamesAvoidEverySourceIdentifier(t *testing.T){in:=fixture("package p\nfunc reorder(a int,b int){}\nfunc call(){reorder(_goforgeArg0(),second())}\n");in.Sources=append(in.Sources,Source{"file:///fixture/other.go","package p\nvar _goforgeArg1 int\n"});out:=run(in);if !out.Passed{t.Fatal(out)};edit:=out.Changes[in.Target.URI][1].NewText;if !strings.Contains(edit,"var _goforgeArg2")||!strings.Contains(edit,"var _goforgeArg3"){t.Fatal(edit)}}
func TestPreservesCRLF(t *testing.T){in:=fixture("package p\r\nfunc reorder(a int,b int){}\r\nfunc call(){\r\n\treorder(1,2)\r\n}\r\n");out:=run(in);if !out.Passed{t.Fatal(out)};edit:=out.Changes[in.Target.URI][1].NewText;if strings.Contains(strings.ReplaceAll(edit,"\r\n",""),"\n")||!strings.Contains(edit,"\r\n\t\tvar"){t.Fatal(edit)}}
func TestRejectsUnsafeStatementShapes(t *testing.T){for name,call:=range map[string]string{"return":"return reorder(1,2)","assignment":"x:=reorder(1,2);_=x","go":"go reorder(1,2)","defer":"defer reorder(1,2)","nested":"sink(reorder(1,2))","label":"L:reorder(1,2);goto L","ellipsis":"reorder(xs...)","tuple":"reorder(pair())","call-comment":"reorder(1,/* keep */2)"}{t.Run(name,func(t *testing.T){in:=fixture("package p\nfunc reorder(a int,b int){}\nfunc call(){"+call+"}\n");if out:=run(in);out.Passed{t.Fatal(out)}})}}
func TestRejectsSignatureScopeExpansion(t *testing.T){for name,spec:=range map[string]string{"delete":"func(b int)","type":"func(b int64,a int)","rename":"func(b int,c int)","duplicate":"func(b int,b int)","result":"func(b int,a int)int","unchanged":"func(a int,b int)","generic":"func[T any](b int,a int)"}{t.Run(name,func(t *testing.T){in:=fixture("package p\nfunc reorder(a int,b int){}\nfunc call(){reorder(1,2)}\n");in.Signature=spec;if out:=run(in);out.Passed{t.Fatal(out)}})}}
func TestRejectsUnsupportedDeclarations(t *testing.T){for name,decl:=range map[string]string{"method":"func(w worker) reorder(a int,b int)","exported":"func Reorder(a int,b int)","grouped":"func reorder(a,b int)","generic":"func reorder[T any](a int,b int)","variadic":"func reorder(a int,b ...int)","comment":"func reorder(a int,/* keep */b int)"}{t.Run(name,func(t *testing.T){s:="package p\ntype worker struct{}\n"+decl+"{}\nfunc call(){reorder(1,2)}\n";in:=fixture(s);at:=strings.Index(s,decl);in.Target.Range=Range{position(s,at),position(s,at)};if out:=run(in);out.Passed{t.Fatal(out)}})}}
func TestRefusesDuplicateAndOutsideReferences(t *testing.T){in:=fixture("package p\nfunc reorder(a int,b int){}\nfunc call(){reorder(1,2)}\n");in.References=append(in.References,in.References[0]);if out:=run(in);out.Passed{t.Fatal(out)};in.References=[]Location{{"file:///outside.go",Range{}}};if out:=run(in);out.Passed{t.Fatal(out)}}
